syntax = "proto3";
package commandes.v1;

service Commandes {
  rpc Lire (LireRequete) returns (Commande);
  rpc Suivre (SuivreRequete) returns (stream Evenement);
}

message Commande {
  string id = 1;
  int64 montant_centimes = 2;
  Statut statut = 3;
}

